
 create role anon; create role authenticated; create role service_role bypassrls;
 create table users(id uuid primary key,status text not null default 'active',role_slug text,can_manage boolean not null default false,display_name text,first_name text,last_name text);
 create table locations(id uuid primary key,status text not null default 'active',owner_id uuid references users(id),name text not null default 'Test salon');
 create function current_public_user_id() returns uuid language sql stable as $$select nullif(current_setting('app.actor',true),'')::uuid$$;
 create function lifecycle_user_is_salon_owner(p_salon uuid,p_user uuid,p_dummy boolean) returns boolean language sql stable security definer as $$select exists(select 1 from locations where id=p_salon and owner_id=p_user)$$;
 create function platform_admin_has_permission(p_code text) returns boolean language sql stable security definer as $$select coalesce((select can_manage from users where id=current_public_user_id()),false)$$;
 create function platform_admin_current_actor() returns table(actor_user_id uuid,actor_membership_id uuid,actor_role_slug text) language sql stable security definer as $$select id,id,role_slug from users where id=current_public_user_id() and role_slug is not null$$;
 create function platform_admin_require_permission(p_code text) returns table(actor_user_id uuid,actor_membership_id uuid,actor_role_slug text) language plpgsql stable security definer as $$begin if not platform_admin_has_permission(p_code) then raise exception 'Platform admin permission denied.'; end if; return query select * from platform_admin_current_actor(); end$$;
 create table platform_admin_audit_logs(id uuid primary key default gen_random_uuid(),actor_user_id uuid references users(id),action text,target_type text,target_id uuid,metadata jsonb not null default '{}');
 create table vietnamese_plugin_subscriptions(salon_id uuid primary key references locations(id),installed boolean not null default true,staff_enabled boolean not null default false,portable_enabled boolean not null default false,trial_ends_at timestamptz not null default now()+interval '5 days',paid_until timestamptz,stripe_subscription text,stripe_customer text,payment_owner uuid,checkout_reference uuid,checkout_owner uuid,checkout_session text,updated_at timestamptz not null default now());
 create table booking_policy_subscriptions(salon_id uuid primary key references locations(id),content text not null default '',published boolean not null default false,paid_until timestamptz,stripe_subscription text,stripe_checkout text,checkout_reference uuid not null default gen_random_uuid(),stripe_customer text,payment_owner uuid,updated_at timestamptz not null default now());
 create table booking_deposit_subscriptions(salon_id uuid primary key references locations(id),enabled boolean not null default false,installed boolean not null default false,mode text not null default 'fixed',value numeric not null default 20,checkout text not null default 'both',stripe_account text,paid_until timestamptz,stripe_subscription text,stripe_checkout text,checkout_reference uuid not null default gen_random_uuid(),stripe_customer text,payment_owner uuid,updated_at timestamptz not null default now());
 create table checkin_receipt_subscriptions(salon_id uuid primary key references locations(id),stripe_subscription text,stripe_checkout text,stripe_customer text,payment_owner uuid,paid_until timestamptz,updated_at timestamptz not null default now());
 create table market_payment_settings(id boolean primary key default true,vietnamese_published boolean not null default true);insert into market_payment_settings values(true,true);
 insert into users(id,role_slug,can_manage,status) values('${admin}','platform_owner',true,'active'),('${owner}',null,false,'active'),('${other}',null,false,'active'),('${operator}','operations_admin',true,'active'),('${suspended}','platform_owner',true,'suspended');
 insert into locations(id,owner_id) values('${salon}','${owner}'),('${otherSalon}','${other}');
 update users set display_name='Owner Display',first_name='First',last_name='Owner' where id='${owner}';
 update users set display_name='',first_name='Second',last_name='Owner' where id='${other}';
 update locations set name='Salon One' where id='${salon}';update locations set name='Salon Two' where id='${otherSalon}';
